mapper.select:
select a.id as approvalId, e.employee_id as employeeId, coalesce(e.employee_name, u.userName) as employeeName, e.mobile as mobile, e.job_number as jobNumber, d.name as deptName, e.post as post, a.tagName as tagName, a.subType as subType, a.bizType as bizType, a.beginTime as beginTime, a.endTime as endTime, a.duration as duration, a.durationUnit as durationUnit, a.durationDay as durationDay, a.workDate as workDate, a.createTime as createTime, a.statisticsStatus as statisticsStatus from tbattendanceapprove a left join tbattendanceuser u on a.userId = u.userId left join hrm_employee e on u.empId = e.employee_id left join hrm_dept d on e.dept_id = d.dept_id where 1 = 1
and ( e.employee_name like concat('%', #{data.search}, '%') or e.job_number like concat('%', #{data.search}, '%') or u.userName like concat('%', #{data.search}, '%') )
and e.employee_id = #{data.employeeId}
and e.dept_id in
#{deptId}
and a.bizType in
#{bizType}
and (
a.tagName like concat('%', #{tagName}, '%')
)
and (
a.subType like concat('%', #{subType}, '%')
)
and date_format(coalesce(a.beginTime, a.endTime, a.workDate), '%Y-%m-%d') <= date_format(#{data.times[1]}, '%Y-%m-%d') and date_format(coalesce(a.endTime, a.beginTime, a.workDate), '%Y-%m-%d') >= date_format(#{data.times[0]}, '%Y-%m-%d')
order by a.beginTime desc, a.createTime desc
